titles.evidence=['Imported browser evidence','Inspect recorded observations, understand their limits, and keep your assessments separate.'];
let storeWarning='';
let st={schema:1,mode:'extension',view:'overview',policy:C.normalizePolicy({}),selected:'overlay',records:[],corrections:[],recovery:[false,false,false,false,false],step:-1,finished:false,current:null,undo:false,inspect:false,filter:'all',search:'',case:'verification-trap',flowNode:'policy',suite:null,lastDuration:null,attentionExpanded:false};
try{const saved=JSON.parse(localStorage.getItem(STORAGE)||'null');if(saved?.schema===1){
 st.policy=C.normalizePolicy(saved.policy||{});st.selected=S.some(s=>s.id===saved.selected)?saved.selected:'overlay';
 st.records=Array.isArray(saved.records)?saved.records.filter(r=>r&&typeof r.id==='string'&&typeof r.timestamp==='string'&&['allow','block','review','observe'].includes(r.decision)&&S.some(s=>s.id===r.scenarioId)).slice(-250):[];
 st.corrections=Array.isArray(saved.corrections)?saved.corrections.filter(r=>r&&typeof r.receiptId==='string'&&['should-allow','should-block','uncertain','approved-once','capability-consumed','capability-rejected','undo','dismissed'].includes(r.kind)).slice(-500):[];
 st.recovery=Array.isArray(saved.recovery)&&saved.recovery.length===5?saved.recovery.map(Boolean):st.recovery;
 }}catch{storeWarning='Saved demo state could not be read. This session is using fresh defaults.';}
